// 사업부·지역별 심층 분석 — 나이키·에르메스처럼 "부문 하나씩 좋은 신호 / 걱정 신호 / 판정 / 다음에 볼 숫자"로 쪼개 본다.
// page.tsx의 DiveBox가 그린다. seg = 부문 자료(/data/segments/{KEY}.json)의 '축 끝부분/멤버 끝부분' → 최근 6분기 성장률을 자동으로 붙인다.
// cur = 공시 자료가 아직 없는 최신 분기나 부문 구분이 없는 회사의 숫자를 직접 넣을 때.
// 텍스트 안의 **굵게** 는 굵은 글씨. 금지 표현(코호트·CAGR·OOS·이격도·파라미터 등)은 쓰지 않는다.
export type DiveState = 'up' | 'hold' | 'watch' | 'down'
export type DiveUnit = {
  name: string
  title: string                 // 이 부문 한 줄 결론
  seg?: string                  // 'StatementGeographicalAxis/EMEAMember' 또는 멤버 끝부분만
  cur?: { yoy?: number; share?: number; margin?: number; txt?: string }
  role: string                  // 회사 안에서 이 부문이 차지하는 자리
  good: string[]; bad: string[]
  state: DiveState
  verdict: string
  next: string
}
export type Dive = {
  asOf: string
  question: string              // 이 회사를 판단할 핵심 질문 하나
  worry: string[]               // 시장이 걱정하는 것(주가가 빠진 이유)
  fact: string[]                // 숫자가 말하는 것
  units: DiveUnit[]
  judge: { k: string; now: string; good: string; bad: string }[]
  verdict: string
  checklist: string[]
}

